Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='testsnamecost', at=datetime(2026, 11, 26, 0, 0, 0), actor='assistant', title='A standing test names the costly thing it guards', body='Keep standing tests for merge and fold laws, order and concurrency, migrations and stored formats, security and privacy boundaries, and end to end scenes. A simple typed transform written as a pure function needs no standing test. A new test states what costly thing it guards.', rationale='Tests that guard nothing costly add reading and gate time and show no gain.', supersedes=()))